/**
 * Expo config plugin: caps the map's tile requests at 4 at a time.
 *
 * Why: the map tiles come from OpenFreeMap, whose terms allow offline area
 * downloads only with at most 4 parallel requests (https://openfreemap.org/tos).
 * MapLibre on Android allows 20 per server and has no setting for it in
 * JavaScript, so this gives it an HTTP client whose dispatcher allows 4.
 * MapLibre still sends its own User-Agent (it names this app), as the terms ask.
 *
 * How: adds a few lines to the generated MainApplication.kt (android/ is
 * generated by prebuild, never edited by hand). MapLibre's classes aren't
 * visible to the app module, so they're looked up by name; if MapLibre ever
 * renames them, the app logs a warning and keeps MapLibre's default.
 *
 * iOS is not covered yet.
 */
const { withMainApplication } = require('expo/config-plugins');

const MAX_REQUESTS_PER_HOST = 4;
const MARKER = 'capMapRequests';

const METHOD = `
  // Added by plugins/with-map-requests.js: at most ${MAX_REQUESTS_PER_HOST} map tile requests
  // at a time, as OpenFreeMap's terms ask for offline downloads.
  private fun ${MARKER}() {
    try {
      // MapLibre's network code needs MapLibre set up first (the map library
      // does it later too; getInstance only sets it up once).
      Class.forName("org.maplibre.android.MapLibre")
        .getMethod("getInstance", android.content.Context::class.java)
        .invoke(null, this)
      val dispatcher = okhttp3.Dispatcher().apply { maxRequestsPerHost = ${MAX_REQUESTS_PER_HOST} }
      val client = okhttp3.OkHttpClient.Builder().dispatcher(dispatcher).build()
      Class.forName("org.maplibre.android.module.http.HttpRequestUtil")
        .getMethod("setOkHttpClient", okhttp3.Call.Factory::class.java)
        .invoke(null, client)
    } catch (e: Exception) {
      android.util.Log.w("MapRequests", "Could not cap map requests; using MapLibre's default", e)
    }
  }
`;

function addMapRequestCap(contents) {
  if (contents.includes(MARKER)) return contents;

  const onCreate = /override fun onCreate\(\) \{\n(\s*)super\.onCreate\(\)\n/;
  if (!onCreate.test(contents)) {
    throw new Error('with-map-requests: could not find onCreate in MainApplication.kt');
  }
  const withCall = contents.replace(onCreate, (match, indent) => `${match}${indent}${MARKER}()\n`);

  // The method goes just before the class's closing brace.
  const end = withCall.lastIndexOf('}');
  return `${withCall.slice(0, end)}${METHOD}}${withCall.slice(end + 1)}`;
}

module.exports = function withMapRequests(config) {
  return withMainApplication(config, (mod) => {
    if (mod.modResults.language !== 'kt') {
      throw new Error('with-map-requests: expected a Kotlin MainApplication');
    }
    mod.modResults.contents = addMapRequestCap(mod.modResults.contents);
    return mod;
  });
};
